import {effectiveTracks,provisionalTracks,QUALITY_OPTIONS,TRACK_LABELS,regionalMatches,outcomeScenario} from './evidence.js?v=0.6.0';
import {uncertaintyPanel,chinaPanel,regionalDetail,inferenceDetail} from './evidence-view.js?v=0.6.0';
import {buildCsv} from './export.js?v=0.6.0';
import {OUTCOMES,OUTCOME_COLORS,placementOf,sortRecords} from './placement.js?v=0.6.0';
import {coverageMarkup,bindCoverage} from './coverage-view.js?v=0.6.0';
import {REGIONS,JOBS,BG,JOB_COLORS,filterRecords,summarize,tally,csvCell,configure,CONFIG} from './core.js?v=0.6.0';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],catalog={},view='overview',filters={period:'cohorts',scope:'all',basis:'final',rank:'all',sort:'year',material:'all',researchMode:'standard',quality:'all',china_region:'CN',china_kind:'placement',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''},comparison='ug_cn',scenarioAssumption=0.5;
const evidenceUI=()=>({panel,table,esc,external,region,percent,option});
const cycleLabel=()=>catalog.current_cycle?catalog.current_cycle.slice(0,4)+'–'+catalog.current_cycle.slice(-2):'当季', archiveLabel=()=>`${catalog.history_years[0]}–${catalog.history_years.at(-1)}`;
const main=$('#main'),fmt=n=>n.toLocaleString('en-US'),percent=x=>x===null?'—':Math.round(x*100)+'%',option=(v,t,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`;
const region=r=>REGIONS[r]||r||'未核验';
const safeUrl=u=>{try{const parsed=new URL(u);return ['http:','https:'].includes(parsed.protocol)?parsed.href:'#'}catch{return '#'}};
const external=(url,label)=>`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
function pageHead(title,sub,eyebrow='RESEARCH, PEOPLE & PLACEMENT'){return `<div class="page-top"><div><p class="eyebrow">${eyebrow}</p><h1>${title}<span class="title-dot">.</span></h1><p class="page-subtitle">${sub}</p></div><span class="outline-badge">核验于 ${esc(catalog.updated_at)}</span></div>`}
function notice(){return `<div class="notice"><strong>持续扩充的核验样本</strong><span>已收录 ${records.length} 人、${new Set(records.map(r=>r.school)).size} 所培养院校。目标范围：北美研究前 50、港五、新加坡三所。名单与首职仍有缺口，比例仅描述已收集记录。<a href="#coverage">查看覆盖情况</a></span></div>`}
function select(name,label,opts){return `<label class="filter-label">${label}<select name="${name}">${opts.map(([v,t])=>option(v,t,filters[name])).join('')}</select></label>`}
function filterPanel(){return `<section class="filter-panel" aria-label="筛选候选人与去向"><div class="filter-top"><div class="segmented" role="group" aria-label="研究领域">${[['all','全部领域'],['marketing','全部 Marketing'],['qm','Quant'],['cb','Consumer Behavior'],['strategy','Strategy'],['marketing_unclassified','Mkt 方向待分'],['io','IO']].map(([v,t])=>`<button type="button" class="segment ${filters.track===v?'selected':''}" data-track="${v}" aria-pressed="${filters.track===v}">${t}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" name="q" value="${esc(filters.q)}" aria-label="搜索姓名、学校、JMP或关键词" placeholder="搜索姓名、学校、JMP…"></label></div><form id="filters"><div class="filter-grid">${select('period','时间口径',[['cohorts',`近四年名录 · ${archiveLabel()} · 含待核验`],['history',`已知首职年 · ${archiveLabel()}`],...catalog.archive_years.map(y=>[String(y),`${y} · placement 年`]),['current',`${cycleLabel()} · 当季求职`],['unresolved','去向 / 首职年待核验'],['all','全部记录 · 含待核验']])}${select('scope','院校范围',[['all','全部档案 · 含 IO'],['target','目标 58 校 · Marketing'],['extension','范围外扩展档案']])}${select('origin','博士培养地区',[['all','全部四个地区'],...['US','CA','HK','SG'].map(r=>[r,region(r)])])}${select('school','博士培养院校',[['all','全部院校'],...[...new Set([...records.map(r=>r.school),...catalog.programs.filter(p=>p.target_scope).map(p=>p.school)])].sort().map(x=>[x,x])])}${select('basis','去向口径',[['final','最终去向 · 含已确定的博后转教职'],['first','首次岗位 · 保留博后阶段']])}${select('rank','培养院校研究排名',[['all','全部排名'],['10','北美前 10'],['25','北美前 25'],['50','北美前 50'],['unranked','无本清单北美名次']])}${select('sort','名录排序',[['year','年份从近到远'],['rank','培养院校研究排名'],['school','培养院校名称']])}${select('background','背景对照口径',Object.entries(BG))}${select('researchMode','研究方向口径',[['standard','当前归档分类'],['include_provisional','加入暂定方向 · 单独标记']])}</div><details class="advanced-filters"><summary>主题、方法、岗位与核验状态</summary><div class="filter-grid">${select('destination','去向地区',[['all','全球去向'],...tally(records,r=>placementOf(r,filters.basis).destination_region).map(([r])=>[r,region(r)])])}${select('job','去向分类',[['all','全部去向'],...Object.entries(OUTCOMES)])}${select('topic','研究主题',[['all','全部主题'],...tally(records,r=>r.topics).map(([t])=>[t,t])])}${select('quality','核验状态',Object.entries(QUALITY_OPTIONS))}${select('material','研究资料',[['all','全部资料'],['jmp','有 JMP 标题'],['homepage','有个人主页'],['cv','有 CV 链接']])}${select('method','研究方法',[['all','全部方法'],...tally(records,r=>r.methods).map(([m])=>[m,m])])}</div></details><div class="filter-bottom"><span id="filter-count" role="status" aria-live="polite"></span><button type="button" class="text-button" id="reset">重置筛选</button></div></form></section>`}
function stats(rs){const s=summarize(rs,filters.basis);return `<div class="stats-grid"><article class="stat-card"><p>筛选内研究者</p><strong>${fmt(s.count)}</strong><span>${s.schools} 所博士培养院校 · 人员去重</span></article><article class="stat-card"><p>已有明确去向类别</p><strong>${fmt(s.known)}</strong><span>未知 ${s.unknown} 人 · 延期 ${s.deferred} 人</span></article><article class="stat-card"><p>教职率 · 终身轨口径</p><strong>${fmt(s.faculty)}<small> / ${s.known}</small></strong><span>${percent(s.facultyShare)} · 分母不含延期与未知</span></article><article class="stat-card dark"><p>当季求职者</p><strong>${fmt(s.onMarket)}</strong><span>筛选内仍在求职者</span></article></div>`}
function panel(title,sub,body,extra=''){return `<section class="panel ${extra}"><div class="panel-heading"><div><p class="eyebrow">${sub}</p><h2>${title}</h2></div></div>${body}</section>`}
function empty(text='没有符合条件的记录'){return `<div class="empty-state"><span>∅</span><h3>${text}</h3><p>可调整筛选，或到“覆盖与来源”查看资料缺口。未知信息不代表不存在。</p><button class="button secondary" data-reset>清除筛选</button></div>`}
function barList(entries,{colors=false,clickable=false}={}){const max=Math.max(1,...entries.map(e=>e[1]));return `<div class="bar-list">${entries.length?entries.slice(0,8).map(([key,n])=>`<div class="bar-row"><div class="bar-label">${clickable?`<button class="text-button" data-destination="${esc(key)}">${esc(region(key))}</button>`:esc(key)}</div><div class="bar-track"><span style="width:${n/max*100}%;background:${colors?JOB_COLORS[key]||'var(--green)':'var(--green)'}"></span></div><span class="bar-number">${n}</span></div>`).join(''):'<p class="muted">当前筛选没有可汇总的已核验记录。</p>'}</div>`}
function annualChart(rs){const hist=rs.filter(r=>r.status==='placed'&&r.market_cycle!==catalog.current_cycle).map(r=>({...r,job_kind:placementOf(r,filters.basis).category}));const years=/^20\d{2}$/.test(filters.period)?[Number(filters.period)]:catalog.history_years,max=Math.max(1,...years.map(y=>hist.filter(r=>r.placement_year===y).length));const used=Object.keys(OUTCOMES).filter(j=>hist.some(r=>r.job_kind===j));return `<div class="annual-chart">${years.map(y=>{const rows=hist.filter(r=>r.placement_year===y);return `<div class="annual-row"><span class="year">${y}</span><div class="annual-track">${rows.length?`<div class="stack" style="width:${rows.length/max*100}%">${used.map(j=>{const n=rows.filter(r=>r.job_kind===j).length;return n?`<button title="${y} · ${OUTCOMES[j]}：${n}人" aria-label="查看${y}年${OUTCOMES[j]}${n}人" data-year="${y}" data-job="${j}" style="flex:${n};background:${OUTCOME_COLORS[j]}">${n}</button>`:''}).join('')}</div>`:'<span class="no-year-data">暂无核验样本</span>'}</div><strong>${rows.length}</strong></div>`}).join('')}<div class="legend">${used.map(j=>`<span><i style="background:${OUTCOME_COLORS[j]}"></i>${OUTCOMES[j]}</span>`).join('')}</div></div><p class="chart-note">横轴按明确的首次入职年份；颜色按所选去向口径。博后转教职者保留首次入职年，最终教职开始年见个人详情。各年收集进度不同，柱高不代表市场规模变化；点击色块可查看明细。</p>`}
function comparisonCard(rs){const baseline=filterRecords(records,{...filters,background:'all'}),sub=baseline.filter(r=>filterRecords([r],{background:comparison}).length);const a=summarize(baseline,filters.basis),b=summarize(sub,filters.basis);return panel('相同筛选下，比较背景','COHORT COMPARISON',`<div class="compare-control"><label for="compare-bg">对照组定义</label><select id="compare-bg">${Object.entries(BG).filter(([k])=>k!=='all').map(([k,v])=>option(k,v,comparison)).join('')}</select></div><div class="compare-grid">${[[a,'整体已收集样本'],[b,BG[comparison]]].map(([s,t])=>`<div class="compare-card"><p>${t}</p><strong>${s.count}<small> 人</small></strong><dl><div><dt>已有明确去向类别</dt><dd>${s.known}</dd></div><div><dt>其中终身轨口径教职</dt><dd>${s.faculty} / ${s.known} <span>${percent(s.facultyShare)}</span></dd></div><div><dt>博士后</dt><dd>${s.postdoc}</dd></div><div><dt>当季求职</dt><dd>${s.onMarket}</dd></div></dl></div>`).join('')}</div><p class="chart-note">对照组是整体样本的子集，并非独立样本。继承上方时间、领域等条件，但用这里的背景定义替代上方背景筛选。教育地区不代表国籍或族裔。<br>${comparison.startsWith('cn_')?'尚无公开身份依据者保留未知，不归为“非中国人／非华裔”。':'本科资料不全可能造成选择偏差。'} 小样本不作显著性或因果判断。</p>`)}
function overview(rs){return uncertaintyPanel(rs,filters.basis,scenarioAssumption,evidenceUI())+`<div class="chart-grid">${panel('首次入职年份与去向分类','FOUR-YEAR ARCHIVE',annualChart(rs))}${panel('全球去向','DESTINATION REGIONS',barList(tally(rs.filter(r=>placementOf(r,filters.basis).destination),r=>placementOf(r,filters.basis).destination_region),{clickable:true})+'<p class="chart-note">按所选去向口径的任职机构所在地归类；港科大（广州）、港中文（深圳）、上海纽约大学、昆山杜克大学均计中国大陆。</p>')}</div><div class="chart-grid equal">${panel('研究主题分布','RESEARCH THEMES',barList(tally(rs,r=>r.topics))+'<p class="chart-note">根据已公开的研究领域和论文内容标注；一人可有多个主题，人数不可直接相加。</p>')}${comparisonCard(rs)}</div>${panel('追溯到具体研究者','RECENT RECORDS',table(rs.slice(0,6))+`<div class="panel-footer"><a href="#directory">查看筛选后的全部名录（${rs.length} 人）</a></div>`)}`}
function trackTags(r){const observed=r.tracks.filter(t=>t!=='marketing'||!r.tracks.some(x=>['qm','cb','strategy'].includes(x)));return observed.map(t=>'<span class="tag '+t+'">'+(t==='marketing'?'Marketing · 方向待分':TRACK_LABELS[t])+'</span>').join('')+provisionalTracks(r).map(t=>'<span class="tag provisional">暂定 '+TRACK_LABELS[t]+(filters.researchMode==='include_provisional'?' · 已纳入筛选':' · 未纳入筛选')+'</span>').join('')}
function researchLinks(r){return '<span class="research-links">'+[[r.homepage,'个人主页'],[r.cv_url,'CV'],[r.jmp_url,'JMP 资料']].filter(([u])=>u).map(([u,l])=>external(u,l)).join(' · ')+'</span>'}
function table(rs){if(!rs.length)return empty();return '<div class="table-scroll"><table class="records-table"><thead><tr><th>研究者 / 培养项目</th><th>研究方向与 JMP</th><th>'+ (filters.basis==='first'?'首次岗位':'最终去向')+'</th><th>时间与资料</th></tr></thead><tbody>'+rs.map(r=>{const p=placementOf(r,filters.basis);return '<tr><td><button type="button" class="person-button" data-person="'+esc(r.id)+'">'+esc(r.name)+'</button><span class="cell-note">'+esc(r.school)+'</span>'+(r.origin_rank?'<span class="tag">UTD 四刊 · 北美 #'+r.origin_rank+'</span>':'')+'<span class="cell-note">'+esc(r.program)+' · '+region(r.origin)+'</span>'+researchLinks(r)+'</td><td>'+trackTags(r)+'<p class="research-title">'+esc(r.fields.slice(0,3).join(' · ')||'研究领域待核验')+'</p>'+(r.jmp?'<span class="cell-note"><strong>JMP：</strong>'+esc(r.jmp)+'</span>':'<span class="cell-note">JMP 尚未确认</span>')+(r.methods.length?'<span class="cell-note">'+esc(r.methods.slice(0,2).join(' · '))+'</span>':'')+'</td><td>'+(p.destination?'<strong class="destination-name">'+esc(p.destination)+'</strong><span class="cell-note">'+esc(p.role||'职位名称未核验')+' · '+region(p.destination_region)+'</span>':'<span class="status-badge">'+OUTCOMES[p.category]+'</span>'+(r.source_reported_placement?'<span class="cell-note">来源所报：'+esc(r.source_reported_placement)+'<br>路径待核验</span>':''))+'<span class="cell-note">'+OUTCOMES[p.category]+'</span>'+(r.final_placement&&r.destination!==r.final_placement.destination?'<span class="tag">含任职路径 · 详情可查</span>':'')+'</td><td><strong>'+(r.status==='on_market'?esc(r.market_cycle?.replace('-','–')||'求职季待核验'):r.placement_year||'首次入职年待核验')+'</strong><span class="cell-note">'+(r.status==='on_market'?'求职季':'首次入职年')+'</span>'+(r.final_placement?.year?'<span class="cell-note">最终去向入职：'+r.final_placement.year+(r.final_placement.status==='announced_future'?' · 已宣布':'')+'</span>':'')+(r.source_cohort_year?'<span class="cell-note">来源名单：'+esc(r.source_cohort_label||r.source_cohort_year)+'</span>':'')+(r.graduation_year?'<span class="cell-note">毕业：'+r.graduation_year+'</span>':'')+'<button class="text-button source-button" data-person="'+esc(r.id)+'">'+r.sources.length+' 个来源</button></td></tr>'}).join('')+'</tbody></table></div>'}
function directory(rs){return `<section class="panel"><div class="panel-heading"><div><p class="eyebrow">TRACEABLE RECORDS</p><h2>${view==='current'?`${cycleLabel()} 候选人`:'Placement 名录'} <span class="count-pill">${rs.length}</span></h2></div><button class="button secondary" id="export-csv">导出当前筛选 CSV</button></div>${table(rs)}</section>`}
function renderResults(){const base=sortRecords(filterRecords(records,filters),filters.sort);let rs=view==='china'?base.filter(r=>regionalMatches(r,filters.china_region,filters.china_kind,filters.basis)):base;$('#filter-count').textContent=`匹配 ${rs.length} 人 · ${new Set(rs.map(r=>r.school)).size} 所培养院校`;$('#summary').innerHTML=stats(rs);$('#results').innerHTML=view==='overview'?overview(rs):view==='china'?chinaPanel(base,rs,filters,evidenceUI()):directory(rs);wireResultActions(rs)}
function wireResultActions(rs){
document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{filters.quality=b.dataset.quality;location.hash='directory';if(view==='directory')mount()});
document.querySelectorAll('[data-china-kind]').forEach(b=>b.onclick=()=>{filters.china_kind=b.dataset.chinaKind;renderResults()});
if($('#china-region'))$('#china-region').onchange=e=>{filters.china_region=e.target.value;renderResults()};
if($('#china-kind'))$('#china-kind').onchange=e=>{filters.china_kind=e.target.value;renderResults()};
if($('#scenario-share'))$('#scenario-share').oninput=e=>{scenarioAssumption=Number(e.target.value)/100;$('#scenario-assumption').textContent=e.target.value+'%';$('#scenario-result').textContent=percent(outcomeScenario(rs,filters.basis,scenarioAssumption).scenario)};
document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>openPerson(b.dataset.person));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=reset);document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{filters.period=b.dataset.year;filters.job=b.dataset.job;location.hash='directory';if(view==='directory')mount()});document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{filters.destination=b.dataset.destination;location.hash='directory';if(view==='directory')mount()});if($('#compare-bg'))$('#compare-bg').onchange=e=>{comparison=e.target.value;renderResults()};if($('#export-csv'))$('#export-csv').onclick=()=>exportCsv(rs)}
function reset(){filters={period:view==='current'?'current':'cohorts',scope:'all',basis:'final',rank:'all',sort:'year',material:'all',researchMode:'standard',quality:'all',china_region:'CN',china_kind:'placement',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''};mount()}
function field(label,value){return `<div><dt>${label}</dt><dd>${esc(value||'未核验')}</dd></div>`}
function openPerson(id){const r=records.find(r=>r.id===id);if(!r)return;let dialog=$('#person-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='person-dialog';dialog.setAttribute('aria-labelledby','person-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()})}dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><p class="eyebrow">RESEARCHER RECORD</p><button class="close-button" aria-label="关闭详情">×</button></div><h2 id="person-title">${esc(r.name)}</h2><p class="muted">${esc(r.school)} · ${esc(r.program)}</p>${trackTags(r)}${researchLinks(r)}<h3>研究</h3><p class="chart-note">JMP（Job Market Paper）是候选人用于学术求职的代表论文。只有来源明确标为 JMP 时才填写；普通论文或博士论文不自动算作 JMP。</p><dl class="detail-grid">${field('Job Market Paper',r.jmp||'来源尚未明确标注')}${r.jmp_evidence?field('JMP 核验依据',r.jmp_evidence):''}${r.origin_rank?field('培养院校排名',`UTD 四刊 2021–2025 · 北美 #${r.origin_rank}`):''}${field('公开研究领域',r.fields.join(' · '))}${field('方法',r.methods.join(' · '))}${r.methods_raw?.length?field('方法原文',r.methods_raw.join(' · ')):''}${field('分类依据',r.field_evidence)}</dl>${inferenceDetail(r,evidenceUI())}<h3>最终去向 · 按已确认求职安排</h3><dl class="detail-grid">${field('机构',placementOf(r).destination)}${field('岗位',placementOf(r).role)}${field('分类',OUTCOMES[placementOf(r).category])}${field('所列岗位开始年',placementOf(r).year)}${field('安排状态',r.final_placement?.status==='announced_future'?'已宣布，尚未开始':'已核验岗位记录')}${field('归类地区',region(placementOf(r).destination_region))}${field('去向依据',r.final_placement?.evidence||'沿用已核验的初始去向；后续安排尚未另行确认')}</dl><h3>首次入职与原始档案</h3><dl class="detail-grid">${field('求职季',r.market_cycle)}${field('首次 placement 年',r.placement_year)}${r.source_cohort_year?field('来源名单年份',r.source_cohort_label||r.source_cohort_year):''}${r.graduation_year?field('博士毕业年',r.graduation_year):''}${field('初始雇主',r.destination)}${r.source_reported_placement?field('来源表所报去向 · 首职待厘清',r.source_reported_placement):''}${field('初始岗位',r.role)}${field('任职地区',region(r.destination_region))}${field('首次岗位类别',OUTCOMES[placementOf(r,'first').category])}</dl>${r.subsequent?.length?`<h3>其他任职经历 · 保留完整路径</h3><ul class="event-list">${r.subsequent.map(s=>`<li><strong>${esc(s.institution||s.employer||s.destination||'')}</strong><span>${esc(s.title||s.role||'')} ${esc(s.start_date||s.start_year||s.year||'')}${s.end_year?'–'+esc(s.end_year):''}</span></li>`).join('')}</ul>`:''}<h3>中国大陆 / 香港的公开活动记录</h3>${regionalDetail(r,evidenceUI())}<h3>背景资料</h3><dl class="detail-grid">${field('本科院校',r.undergraduate?.institution)}${field('本科院校地区',region(r.undergraduate?.region))}${field('中国公民身份',r.identity?.chinese_national?.value==='yes'?'公开明确确认':'无公开核验依据')}${field('华裔身份',r.identity?.chinese_heritage?.value==='yes'?'本人公开自述':'无公开核验依据')}</dl><p class="chart-note">教育背景、国籍和族裔是独立字段；姓名不用于身份判断。</p>${r.research_papers?.length?`<h3>其他研究线索 · 尚未确认为 JMP</h3><ul>${r.research_papers.map(p=>`<li>${external(p.url,p.title)}<p>${esc(p.note)}</p></li>`).join('')}</ul>`:''}${r.notes?`<h3>核验备注</h3><p class="detail-note">${esc(r.notes)}</p>`:''}<h3>公开来源</h3><ul class="source-list">${r.sources.map(s=>`<li>${external(s.url,s.label||'原始资料')}<span>${esc(new URL(safeUrl(s.url),'https://example.com').hostname)}</span></li>`).join('')}</ul><p class="muted">最后核验：${esc(r.checked_at)}</p></div>`;dialog.querySelector('.close-button').onclick=()=>dialog.close();dialog.showModal()}
function exportCsv(rs){const blob=new Blob([buildCsv(rs,filters.basis,filters.researchMode)],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='market-observatory-'+catalog.updated_at+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function coverage(){return pageHead('先看覆盖，再读趋势','按培养项目与来源名单年份，记录名单核对进度和仍待补齐的资料。','COVERAGE & PROVENANCE')+notice()+coverageMarkup(catalog,records)}
function method(){return pageHead('统计口径与使用边界','从公开资料到可比较记录：保留日期、职位和证据的区别。','METHOD & DEFINITIONS')+`<div class="method-grid">`+panel('01 · 范围与研究方向','SCOPE',`<div class="prose"><p>培养地区为美国、加拿大、香港、新加坡；追踪全球去向。目标学校为 UTD 四刊 2021–2025 北美 Marketing 研究前 50、港五和新加坡三所。Economics / IO 保留为扩展档案。</p><p>Marketing 包括 Quant、Consumer Behavior、Strategy 及尚待细分者。一人可以有多个标签。先查本人 CV / 主页，再查院校资料；按内容整理的分类会在个人详情注明，使用机器学习不自动等同 Quant。</p></div>`)+panel('02 · 年份与最终安排','TIME & PLACEMENT',`<div class="prose"><p>求职季、来源名单年、博士毕业年、首次入职年、最终岗位开始年分别保存。毕业年份不自动代替任职年份。近四年名录保留缺日期的人；严格首职年份筛选和年度图只使用有依据的首次入职年。</p><p>默认最终去向指该次求职已确认的最终安排，包含已宣布的先博后再教职；可切换为首次岗位。多年后的普通跳槽不改写原次 placement。尚未开始的岗位标明“已宣布”。未核实后续安排时沿用已确认首职。</p></div>`)+panel('03 · 去向分类','POSITION CATEGORIES',`<div class="prose"><p><strong>教职（终身轨口径）</strong>：Assistant Professor、Tenure-track Researcher，以及英国、澳大利亚、新西兰的 Lecturer；包括已确定先博后再任教职者。</p><p><strong>非终身轨教职</strong>：教学岗（如 AP of Instruction）、Visiting AP、Clinical、Adjunct，以及美国与加拿大的 Lecturer。此类限定词优先于一般 Professor / AP 匹配。</p><p><strong>博后</strong>：Postdoc、Research Fellow、Visiting Scholar 等。<strong>业界及其他</strong>：明确的企业、政府、其他研究机构等去向。<strong>延期</strong>：明确次年重新进入求职市场；已宣布未来教职不等于延期。<strong>未知</strong>：去向或岗位类型资料不足；当季求职者另列。</p><p>这是依公开职位文字执行的统计规则，不表示逐份核验过雇佣合同。大学名称而无岗位信息不能直接算作终身轨；其他地区的 Lecturer 若无进一步证据保留未知。</p></div>`)+panel('04 · 教职率与地区','DENOMINATOR',`<div class="prose"><p><strong>教职率 = 教职人数 ÷（教职 + 非终身轨教职 + 博后 + 业界及其他）。</strong>延期、未知和仍在求职者不进入分母。统计随首次 / 最终去向切换，一人只计一次。</p><p>地区按所选去向机构所在地归类。港科大（广州）、港中文（深圳）、上海纽约大学、昆山杜克大学均计入中国大陆。</p><p>这些比例描述已收集且岗位类别明确的样本。不同学校与年份收集进度不同，不能视为整个市场的就业率或个人求职成功概率。</p></div>`)+panel('05 · 个人资料、JMP 与排名','RESEARCH MATERIALS',`<div class="prose"><p>个人主页、CV 和 JMP 资料链接显示在名录和详情中。JMP（Job Market Paper）是候选人用于学术求职的代表论文；仅在来源明确标注时填写，不以第一篇工作论文或整篇博士论文代替。链接可能指向论文、个人研究页或含标注的 CV。</p><p>培养院校可按 UTD 四刊 2021–2025 北美名次排序，或筛选前 10 / 25 / 50。四刊为 Journal of Marketing、Journal of Marketing Research、Journal of Consumer Research、Marketing Science。该名次属于 Marketing 研究产出，不是综合大学排名、Econ 排名或就业质量排名。</p><p>香港、新加坡及其他无本清单名次的学校保留“无本清单北美名次”，排序时置后，不赋予虚构名次。排名快照随版本保存，年度更新不会静默改变历史选校范围。</p></div>`)+panel('06 · 背景对照','BACKGROUND',`<div class="prose"><p>中国公民身份依据本人或可信公开资料的明确表述；华裔身份依据本人公开自述。每项需要独立来源，不依据姓名、照片或语言推断。</p><p>“本科在中国大陆／香港／台湾”是教育地区对照，不代表国籍或族裔。缺失资料保留未知，不归入否定类别。</p></div>`)+panel('07 · 有依据的暂定分类与情景','INFERENCE',`<div class="prose"><p>新补充的内容推断存为“暂定研究方向”，保留理由和来源，默认不加入子方向筛选。可切换“加入暂定方向”作探索。既有归档标签中也包含按研究内容整理的分类，其依据见个人详情；当前归档分类不等于全部为本人自述。</p><p>缺失去向只做总体情景分析：由你设定未知样本中教职比例，不给个人猜测岗位或年份。极端范围不是置信区间，也不覆盖未收录的人。</p><p>中国地区观察按任职机构、本人明确意向、公开招聘活动分别统计。一般讲座、会议、本科地区与姓名均不用于推定求职意向。所有活动保留当时日期，历史记录不代表当前仍在求职。</p></div>`)+panel('08 · 来源、缺口与维护','PROVENANCE',`<div class="prose"><p>先对照院校名单，再逐人核对 CV、主页和接收单位公告。链接不可读、岗位称谓冲突、只有毕业年等情况会留下具体备注；所查名单对齐不等于整届完整。</p><p>本版：${esc(catalog.version)} · ${esc(catalog.updated_at)}。${esc(catalog.change_note||'')}</p><p>每年更新求职季和最近四年配置，保留历史记录与排名快照。没有自动推定新届名单或把未公开的去向补为零。</p></div>`)+`</div>`}
function mount(){const titles={china:['中国地区的求职与去向','按公开证据观察中国大陆和香港学术市场；历史去向、招聘活动与本人意向分别保存。'],overview:['看见研究的下一站','以研究主题、方法与最终去向，观察 Marketing 全方向和 IO 就业市场。'],directory:['从论文，到 placement','筛选研究者、研究主题和全球去向。点开姓名可查看履历与核验来源。'],current:[`${cycleLabel()}，市场进行中`,'已明确参加本季求职的研究者。名单与结果正在陆续发布；空白去向不代表没有 offer。']};document.querySelectorAll('.nav-item').forEach(a=>{const on=a.hash==='#'+view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(view==='coverage'){main.innerHTML=coverage();bindCoverage(catalog,records,openPerson);return}if(view==='method'){main.innerHTML=method();return}const [title,sub]=titles[view];main.innerHTML=pageHead(title,sub)+notice()+'<div id="summary"></div>'+filterPanel()+'<div id="results"></div><p class="footer-note">每条记录可追溯 · 个人研究用途 · 姓名不用于身份推断 · 最新核验 '+esc(catalog.updated_at)+'</p>';$('#filters').onsubmit=e=>e.preventDefault();$('#filters').onchange=e=>{filters[e.target.name]=e.target.value;if(view==='current'&&e.target.name==='period'&&e.target.value!=='current'){location.hash='directory'}else if(e.target.name==='basis')mount();else renderResults()};$('.search input').oninput=e=>{filters.q=e.target.value;renderResults()};document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{filters.track=b.dataset.track;document.querySelectorAll('[data-track]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});renderResults()});$('#reset').onclick=reset;renderResults()}
function route(){const next=location.hash.slice(1)||'overview';const previous=view;view=['overview','directory','current','china','coverage','method'].includes(next)?next:'overview';if(view==='current'){filters.period='current';filters.job='all'}else if(previous==='current'&&filters.period==='current')filters.period='cohorts';mount()}
try{const responses=await Promise.all([fetch('data/records.json',{cache:'no-cache'}),fetch('data/catalog.json',{cache:'no-cache'})]);if(responses.some(r=>!r.ok))throw new Error('data unavailable');[records,catalog]=await Promise.all(responses.map(r=>r.json()));configure({currentCycle:catalog.current_cycle,historyYears:catalog.history_years});document.querySelector('.nav-item[href="#current"]').innerHTML=`${cycleLabel()} 当季 <span>03</span>`;document.querySelector('.sidebar-foot').innerHTML=`历史档案 + 当季追踪<br><span>核验于 ${esc(catalog.updated_at)}</span>`;route();window.addEventListener('hashchange',route);registerTool()}catch(e){main.innerHTML=pageHead('资料暂未加载','请刷新页面重试；当前不会展示过期或占位的统计数字。')+`<button class="button" id="retry">重新加载</button>`;$('#retry').onclick=()=>location.reload();console.error('Market data load failed',e)}
function registerTool(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_market_records',title:'筛选市场观察记录',description:'Apply the visible search and research-track filters; show matching records and return their names and placements under the selected first/final basis. Public evidence sample, not a census.',inputSchema:{type:'object',properties:{query:{type:'string'},track:{type:'string',enum:['all','marketing','qm','cb','strategy','marketing_unclassified','io']},period:{type:'string',enum:['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','track','period'].includes(k))||input.query!==undefined&&typeof input.query!=='string'||input.track!==undefined&&!['all','marketing','qm','cb','strategy','marketing_unclassified','io'].includes(input.track)||input.period!==undefined&&!['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)].includes(input.period))throw new Error('Invalid market filter');filters={...filters,q:input.query??filters.q,track:input.track??filters.track,period:input.period??filters.period};view='directory';history.replaceState(null,'','#directory');mount();const rs=filterRecords(records,filters);return {count:rs.length,coverage:'partial evidence sample',records:rs.map(r=>({name:r.name,school:r.school,placement:placementOf(r,filters.basis).destination,category:OUTCOMES[placementOf(r,filters.basis).category],basis:filters.basis,first_year:r.placement_year,final_year:r.final_placement?.year,cycle:r.market_cycle}))}}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}catch{}}
